# /// script
# dependencies = ["lunar_python==1.4.8"]
# ///
import importlib.metadata
from datetime import date, timedelta
from itertools import pairwise

from lunar_python import LunarYear, Solar

FIRST_YEAR = 2025
LAST_YEAR = 2060
SOLAR_TERMS = (
    "小寒 大寒 立春 雨水 惊蛰 春分 清明 谷雨 立夏 小满 芒种 夏至 "
    "小暑 大暑 立秋 处暑 白露 秋分 寒露 霜降 立冬 小雪 大雪 冬至"
).split()
# 6tail puts this new moon 25 s after midnight China time, HKO before it; HKO wins
HKO_MONTH_STARTS = {date(2057, 9, 29): date(2057, 9, 28)}
TABLE = """\
// Generated by pi/tools/gen_lunar_table.py from lunar_python {version}. Do not edit.
#include <stddef.h>

#include "calendar/lunar.h"

const int lunar_first_year = {first_year};
const int lunar_last_year = {last_year};

const struct lunar_month lunar_months[] = {{
{months}
}};

const size_t lunar_month_count = sizeof lunar_months / sizeof lunar_months[0];

const struct solar_term_year solar_term_years[] = {{
{terms}
}};

const size_t solar_term_year_count = sizeof solar_term_years / sizeof solar_term_years[0];"""


def lunar_months() -> list[tuple[date, int, bool]]:
    months = []
    for year in range(FIRST_YEAR - 1, LAST_YEAR + 2):
        for month in LunarYear.fromYear(year).getMonthsInYear():
            start = Solar.fromJulianDay(month.getFirstJulianDay())
            start_date = date(start.getYear(), start.getMonth(), start.getDay())
            months.append((start_date, abs(month.getMonth()), month.isLeap()))
    missing = HKO_MONTH_STARTS.keys() - {start for start, _, _ in months}
    if missing:
        raise ValueError(f"6tail no longer starts a month on {sorted(missing)}")
    months = [
        (HKO_MONTH_STARTS.get(start, start), month, leap)
        for start, month, leap in months
    ]
    for (start, _, _), (next_start, _, _) in pairwise(months):
        length = (next_start - start).days
        if length not in (29, 30):
            raise ValueError(f"the month from {start} lasts {length} days")
    first_day = date(FIRST_YEAR, 1, 1)
    last_day = date(LAST_YEAR, 12, 31)
    first = max(i for i, (start, _, _) in enumerate(months) if start <= first_day)
    last = max(i for i, (start, _, _) in enumerate(months) if start <= last_day)
    return months[first : last + 1]


def solar_term_days(year: int) -> list[int]:
    terms = []
    day = date(year, 1, 1)
    while day.year == year:
        name = Solar.fromYmd(day.year, day.month, day.day).getLunar().getJieQi()
        if name:
            terms.append((day, name))
        day += timedelta(days=1)
    in_order = [name for _, name in terms] == SOLAR_TERMS
    two_a_month = all(day.month == i // 2 + 1 for i, (day, _) in enumerate(terms))
    if not (in_order and two_a_month):
        raise ValueError(f"{year} has solar terms {terms}")
    return [day.day for day, _ in terms]


def main() -> None:
    months = "\n".join(
        f"    {{{{{start.year}, {start.month}, {start.day}}}, {month}, {str(leap).lower()}}},"
        for start, month, leap in lunar_months()
    )
    terms = "\n".join(
        f"    {{{year}, {{{', '.join(str(day) for day in solar_term_days(year))}}}}},"
        for year in range(FIRST_YEAR, LAST_YEAR + 1)
    )
    version = importlib.metadata.version("lunar_python")
    print(
        TABLE.format(
            version=version,
            first_year=FIRST_YEAR,
            last_year=LAST_YEAR,
            months=months,
            terms=terms,
        )
    )


if __name__ == "__main__":
    main()
